CREATE TYPE "IssuePriority" AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "IssueStatus" AS ENUM ('OPEN','UNDER_REVIEW','IN_PROGRESS','WAITING_FOR_USER','RESOLVED','CLOSED','REJECTED');
CREATE TYPE "IssueCategory" AS ENUM ('AUTHENTICATION','DASHBOARD','STUDENT_MANAGEMENT','TEACHER_MANAGEMENT','PARENT_PORTAL','CLASS_MANAGEMENT','SUBJECT_MANAGEMENT','CHAPTER_MANAGEMENT','TIMETABLE','ATTENDANCE','ANALYTICS','FEES','NOTIFICATIONS','PUBLIC_WEBSITE','MEDIA_UPLOAD','PERFORMANCE','UI_UX','INCORRECT_DATA','FEATURE_REQUEST','GENERAL_FEEDBACK','OTHER');
CREATE TABLE "IssueReport" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"category" "IssueCategory" NOT NULL,"priority" "IssuePriority" NOT NULL DEFAULT 'MEDIUM',"status" "IssueStatus" NOT NULL DEFAULT 'OPEN',"stepsToReproduce" TEXT,"expectedResult" TEXT,"actualResult" TEXT,"additionalComment" TEXT,"currentRoute" TEXT,"moduleName" TEXT,"browser" TEXT,"operatingSystem" TEXT,"deviceType" TEXT,"screenResolution" TEXT,"applicationVersion" TEXT,"screenshotUrl" TEXT,"screenshotPublicId" TEXT,"reporterId" TEXT NOT NULL,"reporterRole" TEXT NOT NULL,"reporterName" TEXT,"reporterEmail" TEXT,"schoolId" TEXT,"schoolName" TEXT,"assignedToId" TEXT,"platformNote" TEXT,"resolutionNote" TEXT,"firstResponseAt" TIMESTAMP(3),"resolvedAt" TIMESTAMP(3),"closedAt" TIMESTAMP(3),"reopenedCount" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "IssueReport_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IssueReportMessage" ("id" TEXT NOT NULL,"issueId" TEXT NOT NULL,"senderId" TEXT NOT NULL,"senderRole" TEXT NOT NULL,"message" TEXT NOT NULL,"isInternal" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "IssueReportMessage_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IssueReportAudit" ("id" TEXT NOT NULL,"issueId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "IssueReportAudit_pkey" PRIMARY KEY ("id"));
CREATE INDEX "IssueReport_reporterId_createdAt_idx" ON "IssueReport"("reporterId","createdAt"); CREATE INDEX "IssueReport_schoolId_idx" ON "IssueReport"("schoolId"); CREATE INDEX "IssueReport_status_idx" ON "IssueReport"("status"); CREATE INDEX "IssueReport_priority_idx" ON "IssueReport"("priority"); CREATE INDEX "IssueReport_category_idx" ON "IssueReport"("category"); CREATE INDEX "IssueReport_createdAt_idx" ON "IssueReport"("createdAt");
CREATE INDEX "IssueReportMessage_issueId_createdAt_idx" ON "IssueReportMessage"("issueId","createdAt"); CREATE INDEX "IssueReportMessage_senderId_idx" ON "IssueReportMessage"("senderId"); CREATE INDEX "IssueReportAudit_issueId_createdAt_idx" ON "IssueReportAudit"("issueId","createdAt"); CREATE INDEX "IssueReportAudit_actorId_idx" ON "IssueReportAudit"("actorId");
ALTER TABLE "IssueReport" ADD CONSTRAINT "IssueReport_reporterId_fkey" FOREIGN KEY ("reporterId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "IssueReport" ADD CONSTRAINT "IssueReport_assignedToId_fkey" FOREIGN KEY ("assignedToId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "IssueReport" ADD CONSTRAINT "IssueReport_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "IssueReportMessage" ADD CONSTRAINT "IssueReportMessage_issueId_fkey" FOREIGN KEY ("issueId") REFERENCES "IssueReport"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "IssueReportMessage" ADD CONSTRAINT "IssueReportMessage_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "IssueReportAudit" ADD CONSTRAINT "IssueReportAudit_issueId_fkey" FOREIGN KEY ("issueId") REFERENCES "IssueReport"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "IssueReportAudit" ADD CONSTRAINT "IssueReportAudit_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
